import pg from 'pg';
let pool;
export function ownerDatabase() {
 const connectionString=process.env.OWNER_DATABASE_URL;
 if(!connectionString)throw new Error('OWNER_DATABASE_URL_REQUIRED');
 const url=new URL(connectionString);
 const local=['localhost','127.0.0.1','::1'].includes(url.hostname);
 if(process.env.NODE_ENV==='production' && (local || ['disable','no-verify','prefer'].includes(url.searchParams.get('sslmode'))))throw new Error('OWNER_DATABASE_TLS_REQUIRED');
 if(!local){url.searchParams.delete('sslmode');url.searchParams.delete('ssl');}
 pool??=new pg.Pool({connectionString:url.toString(),max:4,connectionTimeoutMillis:5000,idleTimeoutMillis:30000,statement_timeout:10000,...(!local?{ssl:{rejectUnauthorized:true}}:{})});
 if(pool.listenerCount('error')===0)pool.on('error',()=>{});
 const wrap=client=>({query:(sql,values)=>client.query(sql,values),transaction:async fn=>{const c=await pool.connect();try{await c.query('BEGIN');const result=await fn(wrap(c));await c.query('COMMIT');return result;}catch(e){await c.query('ROLLBACK');throw e;}finally{c.release();}}});
 return wrap(pool);
}
